    "*:disabled { color: #a3a3a3; }\n"
    "selection, *:selected { background-color: #d2d2d2; color: #000000; }\n"
    "\n"
    "/* ---------- type ---------- */\n"
    "label { color: #333333; }\n"
    "label.h1 { font-family: \"Fraunces\"; font-weight: 300; font-size: 48px; color: #111111; }\n"
    "label.h2 { font-family: \"Fraunces\"; font-weight: 300; font-size: 34px; color: #111111; }\n"
    "label.h3 { font-family: \"Space Grotesk\"; font-weight: 500; font-size: 20px; color: #111111; }\n"
    "label.label { font-family: \"Space Grotesk\"; font-weight: 500; font-size: 11px; letter-spacing: 2.42px; color: #5c5c5c; }\n"
    "label.muted { color: #5c5c5c; }\n"
    "label.faint { color: #858585; }\n"
    "label.mono { font-family: \"Space Mono\"; font-size: 12px; color: #333333; }\n"
    "label.stat { font-family: \"Fraunces\"; font-weight: 300; font-size: 34px; color: #111111; }\n"
    "link { color: #000000; }\n"
    "\n"
    "/* ---------- containers ---------- */\n"
    ".card { background-color: #e9e9e9; border: 1px solid #bcbcbc; border-radius: 0px; padding: 14px 16px; }\n"
    ".stats { border: 1px solid #bcbcbc; border-radius: 0px; }\n"
    ".cell { border-right: 1px solid #bcbcbc; padding: 12px 14px 10px; }\n"
    ".cell:last-child { border-right: none; }\n"
    "separator { background-color: #bcbcbc; min-width: 1px; min-height: 1px; }\n"
    "frame > border { border: 1px solid #bcbcbc; border-radius: 0px; }\n"
    "frame > label { color: #5c5c5c; }\n"
    "scrolledwindow { background: transparent; }\n"
    "\n"
    "/* ---------- buttons ---------- */\n"
    "button {\n"
    "  background-image: none; background-color: transparent; color: #111111; text-shadow: none; box-shadow: none;\n"
    "  border: 1px solid #111111; border-radius: 0px; min-height: 38px; padding: 0 18px;\n"
    "  font-family: \"Space Grotesk\"; font-weight: 500; font-size: 11px; letter-spacing: 1.55px;\n"
    "  transition: background-color 150ms, border-color 150ms;\n"
    "}\n"
    "button:hover { background-color: #e7e7e7; }\n"
    "button:active, button:checked { background-color: #111111; color: #f2f2f2; border-color: #111111; }\n"
    "button:disabled { color: #a3a3a3; border-color: #bcbcbc; background-color: transparent; }\n"
    "button.fill, button.suggested-action { background-color: #111111; color: #f2f2f2; border-color: #111111; }\n"
    "button.fill:hover, button.suggested-action:hover { background-color: #3a3a3a; border-color: #3a3a3a; }\n"
    "button.fill label, button.suggested-action label { color: #f2f2f2; }\n"
    "button.line { border-color: #868686; }\n"
    "button.line:hover { border-color: #111111; }\n"
    "button.ghost, button.flat { border-color: transparent; color: #5c5c5c; }\n"
    "button.ghost:hover, button.flat:hover { color: #111111; background-color: #e7e7e7; }\n"
    "button.destructive-action { border-color: #111111; border-style: dashed; }\n"
    "button label { color: inherit; }\n"
    "\n"
    "/* ---------- inputs ---------- */\n"
    "entry, spinbutton:not(.vertical), textview text {\n"
    "  background-image: none; background-color: #ffffff; color: #111111; box-shadow: none;\n"
    "  border: 1px solid #bcbcbc; border-radius: 0px; min-height: 38px; padding: 0 10px;\n"
    "  caret-color: #000000;\n"
    "}\n"
    "textview { background-color: #ffffff; }\n"
    "textview text { padding: 6px 8px; }\n"
    "entry:hover { border-color: #868686; }\n"
    "entry:focus, spinbutton:focus { border: 1px solid #111111; }\n"
    "entry placeholder, entry .dim-label { color: #858585; }\n"
    "spinbutton entry { border: none; border-radius: 0; background: transparent; min-height: 0; }\n"
    "spinbutton button { border: none; border-left: 1px solid #bcbcbc; border-radius: 0; min-height: 0; padding: 0 8px; }\n"
    "combobox button.combo, dropdown button { background-color: #ffffff; border-color: #bcbcbc; color: #111111; }\n"
    "combobox button.combo:hover { border-color: #868686; }\n"
    "combobox arrow, menubutton arrow { -gtk-icon-source: none; background-image: url(\"@MONO_ICONS@/chevron-down.svg\"); background-repeat: no-repeat; background-position: center; background-size: 10px 10px; min-width: 12px; min-height: 12px; }\n"
    "\n"
    "/* ---------- check / radio / switch ---------- */\n"
    "check, radio {\n"
    "  background-image: none; background-color: #ffffff; border: 1px solid #868686; min-width: 14px; min-height: 14px;\n"
    "  margin: 0 8px 0 0; color: #f2f2f2; -gtk-icon-source: none;\n"
    "}\n"
    "check { border-radius: 0px; }\n"
    "radio { border-radius: 100%; }\n"
    "check:hover, radio:hover { border-color: #111111; }\n"
    "check:checked { background-color: #111111; border-color: #111111; -gtk-icon-source: url(\"@MONO_ICONS@/check.svg\"); }\n"
    "check:indeterminate { background-color: #111111; border-color: #111111; -gtk-icon-source: url(\"@MONO_ICONS@/dash.svg\"); }\n"
    "radio:checked { border-color: #111111; -gtk-icon-source: url(\"@MONO_ICONS@/radio.svg\"); }\n"
    "switch { background-color: #ffffff; border: 1px solid #868686; border-radius: 0px; min-width: 36px; min-height: 18px; color: transparent; font-size: 0; }\n"
    "switch slider { background-image: none; box-shadow: none; background-color: #5c5c5c; border: none; border-radius: 0px; min-width: 14px; min-height: 14px; margin: 1px; }\n"
    "switch:checked { background-color: #111111; border-color: #111111; }\n"
    "switch:checked slider { background-image: none; background-color: #f2f2f2; }\n"
    "\n"
    "/* ---------- sliders & progress ---------- */\n"
    "scale trough { background-color: #868686; min-height: 2px; min-width: 2px; border-radius: 1px; border: none; }\n"
    "scale trough highlight { background-image: none; background-color: #111111; border: none; border-radius: 1px; }\n"
    "scale slider { background-color: #000000; border: none; min-width: 14px; min-height: 14px; margin: -6px; border-radius: 0px; box-shadow: none; }\n"
    "progressbar trough { background-color: #dcdcdc; min-height: 4px; border: none; border-radius: 0px; }\n"
    "progressbar progress { background-color: #111111; min-height: 4px; border: none; border-radius: 0px; }\n"
    "levelbar block.filled { background-color: #111111; }\n"
    "levelbar block.empty { background-color: #dcdcdc; }\n"
    "\n"
    "/* ---------- notebook (tabs) ---------- */\n"
    "notebook { background-color: transparent; }\n"
    "notebook > header { background-color: transparent; border: none; box-shadow: none; }\n"
    "notebook > header.top { border-bottom: 1px solid #bcbcbc; }\n"
    "notebook > header tab { background-color: transparent; border: 1px solid transparent; border-bottom: none; padding: 6px 14px;\n"
    "  border-radius: 0px 0px 0 0; color: #5c5c5c; box-shadow: none; }\n"
    "notebook > header tab label { font-family: \"Space Grotesk\"; font-weight: 500; font-size: 11px; color: inherit; }\n"
    "notebook > header tab:hover { color: #111111; }\n"
    "notebook > header tab:checked { color: #111111; border-color: #bcbcbc; background-color: #f2f2f2; margin-bottom: -1px; }\n"
    "notebook > stack { background-color: #f2f2f2; }\n"
    "\n"
    "/* ---------- lists & trees ---------- */\n"
    "list, treeview.view, iconview { background-color: #ffffff; color: #111111; }\n"
    "list { border: 1px solid #bcbcbc; border-radius: 0px; }\n"
    "list row { padding: 6px 10px; border-radius: 0px; }\n"
    "list row:hover { background-color: #e7e7e7; }\n"
    "list row:selected { background-color: #d2d2d2; color: #000000; }\n"
    "treeview.view header button { background-color: #ffffff; color: #5c5c5c; border: none; border-bottom: 1px solid #bcbcbc;\n"
    "  border-radius: 0; min-height: 0; padding: 6px 8px; font-size: 11px; }\n"
    "treeview.view:selected { background-color: #d2d2d2; color: #000000; }\n"
    "\n"
    "/* ---------- menus, popovers, tooltips ---------- */\n"
    "menubar { background-color: #f2f2f2; border-bottom: 1px solid #dcdcdc; }\n"
    "menu, .menu, popover, popover.background { background-color: #e9e9e9; color: #111111; border: 1px solid #868686; border-radius: 0px; }\n"
    "menuitem { padding: 6px 12px; }\n"
    "menuitem:hover { background-color: #d2d2d2; color: #000000; }\n"
    "tooltip, tooltip.background { background-color: #e4e4e4; color: #111111; border: 1px solid #868686; border-radius: 0px; }\n"
    "tooltip label { font-family: \"Space Mono\"; font-size: 12px; color: #111111; }\n"
    "\n"
    "/* ---------- headerbar / statusbar ---------- */\n"
    "headerbar { background-image: none; background-color: #f2f2f2; border-bottom: 1px solid #dcdcdc; box-shadow: none; min-height: 40px; }\n"
    "headerbar .title { font-family: \"Space Grotesk\"; font-weight: 500; color: #111111; }\n"
    "headerbar .subtitle { color: #5c5c5c; }\n"
    "statusbar { background-color: #ffffff; border-top: 1px solid #dcdcdc; color: #5c5c5c; }\n"
    "statusbar label { font-family: \"Space Mono\"; font-size: 12px; color: #5c5c5c; }\n"
    "\n"
    "/* ---------- scrollbars ---------- */\n"
    "scrollbar { background-color: transparent; border: none; }\n"
    "scrollbar slider { background-color: #868686; border: none; border-radius: 0px; min-width: 6px; min-height: 6px; }\n"
    "scrollbar slider:hover { background-color: #5c5c5c; }\n"
    "\n";

